export function initial(){return {version:2,graduation:'Not set',terms:['Spring 2027','Fall 2027','Spring 2028'],abroad:false,abroadTerm:'Fall 2028',includeIP:true,checks:[false,false,false,false],courses:[],plan:[],example:false};}
export function example(){return {...initial(),graduation:'Spring 2028',example:true,courses:[{code:'CS 7641',title:'Machine Learning',credits:3,designation:'ms',grade:'B',kind:'ml',approved:false},{code:'CS 6220',title:'Big Data Systems & Analysis',credits:3,designation:'ms',grade:'IP',kind:'elective',approved:false}]};}
export function eligible(c,s){return c.designation!=='bs' && (c.grade==='IP'?s.includeIP:['A','B','C'].includes(c.grade));}
export function totals(s){const count=s.courses.filter(c=>eligible(c,s));const spec=count.filter(c=>c.grade!=='C');const alg=Math.min(3,spec.filter(c=>c.kind==='alg').reduce((n,c)=>n+c.credits,0));const ml=Math.min(3,spec.filter(c=>c.kind==='ml').reduce((n,c)=>n+c.credits,0));const elect=Math.min(9,spec.filter(c=>c.kind==='elective').reduce((n,c)=>n+c.credits,0));const credits=count.reduce((n,c)=>n+c.credits,0);const free=Math.min(15,Math.max(0,credits-alg-ml-elect));const limited=count.filter(c=>!/^CS |^CSE /.test(c.code)||Number(c.code.split(' ')[1])<6000).reduce((n,c)=>n+c.credits,0);const graduate=count.filter(c=>/^CS |^CSE /.test(c.code)&&Number(c.code.split(' ')[1])>=6000).reduce((n,c)=>n+c.credits,0);const earned=count.filter(c=>c.grade!=='IP').reduce((n,c)=>n+c.credits,0);return {credits,earned,alg,ml,elect,free,limited,graduate,remaining:Math.max(0,30-credits),pending:count.filter(c=>!c.approved).length};}
export function coverage(s){return totals({...s,courses:[...s.courses,...s.plan.map(c=>({...c,designation:'ms',grade:'IP'}))],includeIP:true});}
export function normalizeCourse(code,title){code=code.toUpperCase().trim().replace(/\s+/g,' ');if(!/^[A-Z]{2,5} [4-8]\d{3}$/.test(code))throw Error('Enter a course code such as CS 7641, at level 4000–8000.');const known=CATALOG.find(c=>c.code===code);return known?{...known}:{code,title:title.trim(),credits:3,kind:'free'};}
function validCourse(c){if(!c||typeof c.code!=='string'||typeof c.title!=='string'||c.title.length<1||c.title.length>120||!Number.isInteger(c.credits)||c.credits<1||c.credits>6||!['ml','alg','elective','free'].includes(c.kind))return false;try{const normalized=normalizeCourse(c.code,c.title);return normalized.code===c.code&&normalized.kind===c.kind&&normalized.title===c.title;}catch{return false}}
export function validateState(s){if(!s||s.version!==2||typeof s.abroad!=='boolean'||typeof s.example!=='boolean'||typeof s.includeIP!=='boolean'||!['Not set',...TERMS].includes(s.graduation)||!TERMS.includes(s.abroadTerm)||!Array.isArray(s.terms)||s.terms.length!==3||s.terms.some(t=>!TERMS.includes(t))||new Set(s.terms).size!==3||!Array.isArray(s.courses)||s.courses.length>100||!Array.isArray(s.plan)||s.plan.length>100||!Array.isArray(s.checks)||s.checks.length!==4||s.checks.some(x=>typeof x!=='boolean'))return false;
 return s.courses.every(c=>validCourse(c)&&['double','ms','bs'].includes(c.designation)&&['A','B','C','D','F','IP'].includes(c.grade)&&typeof c.approved==='boolean')&&s.plan.every(c=>validCourse(c)&&s.terms.includes(c.term))&&new Set(s.courses.map(c=>c.code)).size===s.courses.length&&new Set(s.plan.map(c=>c.code)).size===s.plan.length&&!s.plan.some(c=>s.courses.some(x=>x.code===c.code&&x.designation!=='bs'));}
